function ScoreForm({ players, onSelectPlayer, score, onAddScore }) {
	const playerObj = players.map((player) => player);

	const {
		id,
		playerName,
		points,
		wins,
		draws,
		losses,
		goalsFor,
		goalsAgainst,
		goalDifference,
	} = playerObj;

	function handleSubmit(e) {
		e.preventDefault();
	}
	return (
		<form onSubmit={handleSubmit}>
			<span>
				Score:
				<select
					value={playerName}
					onChange={(e) => onSelectPlayer(e.target.value)}
				>
					<option value={playerObj[0].playerName}>
						{playerObj[0].playerName}
					</option>
					<option value={playerObj[1].playerName}>
						{playerObj[1].playerName}
					</option>
					<option value={playerObj[2].playerName}>
						{playerObj[2].playerName}
					</option>
				</select>
				Score: (input a value)
			</span>
			:
			<span>
				<select
					value={playerName}
					onChange={(e) => onSelectPlayer(e.target.value)}
				>
					<option value={playerObj[0].playerName}>
						{playerObj[0].playerName}
					</option>
					<option value={playerObj[1].playerName}>
						{playerObj[1].playerName}
					</option>
					<option value={playerObj[2].playerName}>
						{playerObj[2].playerName}
					</option>
				</select>
				Score: (input a value)
			</span>
			<button>Add</button>
		</form>
	);
}
export default ScoreForm;
